//MARK: Civ Select Ticket Item
export interface CivTicketItemProps {
	requiredAge: string;
	selectedAge: string;
	alwaysAvailable?: boolean;
}

const CivSelectTicketItemComponent: ParentComponent<CivTicketItemProps> = (props) => {
	const model = useCivSelectModelContext();
	const civ = createMemo(() => model.viewCiv() ?? model.selectedCiv());
	const isApexAgeSelected = createMemo(() => civ().apexAge == props.selectedAge);
	const audio = useAudio("CivilizationDetails");
	onMount(() => {
		audio("popup-open");
	});

	return (
		<div
			class="civ-details-card-outer mt-4"
			classList={{ apex: isApexAgeSelected() || props.alwaysAvailable }}
		>
			<div class="civ-details-card-inner">{props.children}</div>
			<Show when={!props.alwaysAvailable}>
				<div class="flex items-center justify-center">
					<TotIcon
						class="-mt-4 size-10"
						isApexAge={isApexAgeSelected()}
					/>
					<span class="uppercase text-accent-2 ml-4 mt-1 mb-2">
						<Show
							when={!isApexAgeSelected()}
							fallback={<L10n.Compose text="LOC_UI_CREATE_GAME_AVAILABLE_APEX_AGE" />}
						>
							<L10n.Compose
								text="LOC_UI_CREATE_GAME_AVAILABLE_IN_THE_AGE"
								args={[civ().ageName]}
							/>
						</Show>
					</span>
				</div>
			</Show>
		</div>
	);
};

export const CivSelectTicketItem = ComponentRegistry.register("CivSelectTicketItem", CivSelectTicketItemComponent);

//MARK: Civ Select BUILDINGS Ticket Item
export interface CivBuildingsTicketItemProps {
	requiredAge: string;
	selectedAge: string;
}

const CivSelectBuildingsTicketItemComponent: ParentComponent<CivBuildingsTicketItemProps> = (props) => {
	interface AgeData {
		label: string;
		value: number;
	}

	const ages = new Map<string, AgeData>([]);

	Database.query("config", "SELECT * FROM Ages")?.forEach((row) => {
		ages.set(
			row.AgeType as string,
			{
				label: row.AgeType as string,
				value: row.ChronologyIndex as number,
			} as AgeData,
		);
	});

	const model = useCivSelectModelContext();
	const ageModel = useAgeSelectModelContext();
	const civ = createMemo(() => model.viewCiv() ?? model.selectedCiv());
	const isApexAgeSelected = createMemo(() => civ().apexAge == props.selectedAge);
	const isBeforeApexAge = createMemo(() => ages.get(civ().apexAge)!.value > ages.get(props.selectedAge)!.value);
	const isAfterApexAge = createMemo(() => ages.get(civ().apexAge)!.value < ages.get(props.selectedAge)!.value);

	const avalaibilityLabel = createMemo(() => {
		if (isApexAgeSelected()) {
			return "LOC_UI_CREATE_GAME_AVAILABLE_APEX_AGE";
		}

		if (isBeforeApexAge()) {
			return Locale.compose(
				"LOC_UI_CREATE_GAME_AVAILABLE_IN_THE_AGE",
				ageModel.getAgeName(civ().apexAge) as string,
			);
		}

		if (isAfterApexAge()) {
			return "LOC_UI_CREATE_GAME_AVAILABLE";
		}

		return "";
	});

	return (
		<div
			class="civ-details-card-outer mt-4"
			classList={{
				apex: isApexAgeSelected() || isAfterApexAge(),
			}}
		>
			<div class="civ-details-card-inner">{props.children}</div>
			<div class="flex items-center justify-center">
				<TotIcon
					class="-mt-4 size-10"
					isApexAge={isApexAgeSelected()}
				/>
				<span class="uppercase text-accent-2 ml-4 mt-1 mb-2">
					<L10n.Compose text={avalaibilityLabel()} />
				</span>
			</div>
		</div>
	);
};

