interface UnlocksTabProps {
	isUnlocks?: boolean;
	isInGame?: boolean;
}

//MARK: CIV UNLOCKS INFO
const CivUnlocksInfoComponent: Component<UnlocksTabProps> = (props) => {
	const model = useCivSelectModelContext();
	const civ = createMemo(() => model.viewCiv() ?? model.selectedCiv());
	const civUnlocks = createMemo(() => civ().unlocks);
	const civUnlockedBy = createMemo(() => civ().unlockedBy);
	const syncretismUnlocks = createMemo(() => civ().syncretismUnlocks);
	const [isTracked, setIsTracked] = createSignal(false);

	const [civUnlockTrackingManager, setCivUnlockTrackingManager] = createSignal<CivUnlockTrackingManager | null>(
		UI.isInGame() ? getCivUnlockTrackingManager() : null,
	);

	const refreshCivUnlockTrackingManager = () => {
		setCivUnlockTrackingManager(UI.isInGame() ? getCivUnlockTrackingManager() : null);
	};

	onMount(() => {
		window.addEventListener(QuestTrackerRefreshRequestName, refreshCivUnlockTrackingManager);

		onCleanup(() => {
			window.removeEventListener(QuestTrackerRefreshRequestName, refreshCivUnlockTrackingManager);
		});
	});

	const canTrack = createMemo(() => {
		const manager = civUnlockTrackingManager();

		return props.isUnlocks && (manager?.canTrack(civ().civID) ?? false);
	});

	createEffect(
		on(
			() => [civ().civID, civUnlockTrackingManager()] as const,
			([civID, manager]) => {
				setIsTracked(manager?.isTracked(civID) ?? false);
			},
		),
	);

	return (
		<div class="flex flex-col h-full text-accent-2">
			<div class="flex flex-row justify-between">
				<CivInfoHeader />
				<div class="h-0 overflow-visible">
					<AgePreview />
				</div>
			</div>
			{/* <div
				class={`h-2 w-full bg-cover mb-2 mt-2`}
				style={{ "background-image": "url(blp:shell_line-divider)" }}
			/> */}
			<div class="civ-select-divider my-2" />
			<ScrollArea
				class="flex-auto -mr-8 mb-4"
				reserveSpace={true}
				useProxy={true}
			>
				<Show when={civUnlockedBy().length > 0}>
					<div class="text-lg font-title uppercase font-bold text-secondary">
						<L10n.Compose text="LOC_UI_CREATE_GAME_UNLOCKED_BY" />
					</div>
					<div class="text-sm mb-2">
						<L10n.Compose text="LOC_UI_CREATE_GAME_UNLOCKED_BY_DESCRIPTION" />
					</div>
					<Show when={canTrack()}>
						<div class="flex flex-row items-center w-full my-2">
							<div
								class="h-2 flex-auto bg-cover mr-2"
								style={{ "background-image": "url(blp:shell_line-divider)" }}
							/>
							<CheckBox
								class="size-6"
								isChecked={isTracked()}
								onActivate={() => {
									const civType = civ().civID;
									const manager = civUnlockTrackingManager();
									if (manager != null) {
										if (manager.isTracked(civType)) {
											manager.untrackCivUnlock(civType);
											setIsTracked(false);
											return;
										}

										manager.trackCivUnlock(civType);
										setIsTracked(manager.isTracked(civType));
									}
								}}
							/>
							<div class="uppercase ml-2 font-title text-secondary">
								<L10n.Compose text="LOC_LEGACIES_TRACK" />
							</div>
							<div
								class="h-2 flex-auto bg-cover ml-2"
								style={{ "background-image": "url(blp:shell_line-divider)" }}
							/>
						</div>
					</Show>
					<Show when={!UI.isInGame()}>
						<L10n.Stylize text="LOC_UI_CREATE_GAME_UNLOCKED_BY_SUBTITLE" />
					</Show>
					<For each={civUnlockedBy()}>
						{(unlockedBy, _) => (
							<div class="flex flex-row flex-wrap w-full">
								<Show
									when={props.isUnlocks}
									fallback={<span>• </span>}
								>
									<CheckBox
										class="size-6"
										isChecked={unlockedBy.isUnlocked}
										disabled={true}
										disableFocus={true}
									/>
								</Show>
								<L10n.Stylize
									class="flex-auto create-game-markup tight"
									text={unlockedBy.text}
								/>
							</div>
						)}
					</For>
				</Show>
				<Show when={civUnlocks().length > 0}>
					<div class="text-lg font-title uppercase font-bold text-secondary mt-3">
						<L10n.Compose text="LOC_CREATE_GAME_AGE_UNLOCK_TITLE" />
					</div>
					<div class="text-sm mb-2">
						<L10n.Compose text="LOC_CREATE_GAME_AGE_UNLOCK_SUBTITLE" />
					</div>
					<For each={civUnlocks()}>
						{(unlock) => (
							<div class="flex flex-row flex-wrap w-full">
								<span>• </span>
								<L10n.Stylize
									class="create-game-markup tight"
									text={unlock}
								/>
							</div>
						)}
					</For>
				</Show>
				<Show when={syncretismUnlocks() && syncretismUnlocks()!.length > 0}>
					<div class="text-lg font-title uppercase font-bold text-secondary mt-3">
						<L10n.Compose text="LOC_CREATE_GAME_UNLOCK_ITEM_SYNCRETISM_TITLE" />
					</div>
					<div class="text-sm mb-2">
						<L10n.Stylize text="LOC_CREATE_GAME_UNLOCK_ITEM_SYNCRETISM_DESCRIPTION" />
					</div>
					<div class="flex flex-col items-start">
						<For each={syncretismUnlocks()}>
							{(unlock) => (
								<div class="flex flex-row flex-wrap w-full">
									<SyncretismTooltip
										initialHPosition={TooltipHorizontalPosition.RIGHT}
										initialVPosition={TooltipVerticalPosition.BOTTOM}
										offset={10}
										civilizationType={unlock.civilization}
									>
										<L10n.Stylize
											class="create-game-markup tight mb-1"
											classList={{
												"faux-tooltip-controller": !IsControllerActive(),
											}}
											text={unlock.description}
										/>
									</SyncretismTooltip>
								</div>
							)}
						</For>
					</div>
				</Show>
			</ScrollArea>
		</div>
	);
};

export const CivUnlocksInfo = ComponentRegistry.register("CivUnlocksInfo", CivUnlocksInfoComponent);

const CivDetailsComponent: Component = () => {
	const flowContext = useScreenFlowContext();
	const model = useCivSelectModelContext();

	const isInGame = UI.isInGame();

	return (
		<CreateGameStage
			header={
				<CreateGameStageHeader
					showSteps={!(ViewExperience() == UIViewExperience.Handheld) && !UI.isInGame()}
					title="LOC_UI_CREATE_GAME_CIVILIZATION_DETAILS"
					onBack={() => flowContext.activate("civ-select")}
					hideButtonText={isInGame ? "LOC_UI_AGE_TRANSITION_VIEW_MAP" : undefined}
				/>
			}
			backgroundImage={model.selectedCiv().bgImage}
			backgroundOpacity={0.4}
			addTextBgGradient={true}
			mode={isInGame ? CreateGameStageMode.StageOnly : CreateGameStageMode.Full}
		>
			<CivDetailsBase />
		</CreateGameStage>
	);
};

export const CivDetailsBase = () => {
	const model = useCivSelectModelContext();
	const ageModel = useAgeSelectModelContext();
	//const totModel = useTotModelContext();
	const civ = createMemo(() => model.viewCiv() ?? model.selectedCiv());
	const [selectedAge, setSelectedAge] = createSignal(ageModel.selectedAge.type);

	const isInGame = UI.isInGame();
	const isUnlocks = isInGame && !!ContextManager.getTarget("screen-legacies");
	const ageSuccessor = isInGame ? GameInfo.AgeSuccessors.lookup(Game.age) : null;
	const hasNextAge = ageSuccessor != null && GameInfo.Ages.find((a) => a.AgeType == ageSuccessor.SuccessorAgeType);

	const isMobile = ViewExperience() == UIViewExperience.Mobile;
	const isSmallScreen = useIsSmallScreen();

	let flowContext: ScreenFlowContextProvider | undefined = undefined;
	if (!isUnlocks) {
		flowContext = useScreenFlowContext();
	}

	// When starting age changes, update the displayed age
	createEffect(
		on(
			() => ageModel.selectedAge.type,
			(age) => setSelectedAge(age),
		),
	);

	return (
		<div class={`flex flex-row h-full relative ${isUnlocks ? "w-full" : ""}`}>
			<div class="flex flex-row flex-auto items-start">
				<div class="flex flex-col items-center h-full civ-details-left-content">
					<Hotkeys hotkeys={[{ hotkeyAction: "accept", navTrayText: "LOC_GENERIC_SELECT" }]} />
					<Icon
						name={`url('${civ().icon ?? ""}')`}
						isUrl={true}
						class={`${isMobile && isUnlocks && isSmallScreen() ? "size-36" : "size-40"}`}
					/>
					<L10n.Stylize
						text={
							isUnlocks
								? !hasNextAge
									? "LOC_LEGACIES_CURRENT_AGE"
									: "LOC_LEGACIES_UPCOMING_AGE"
								: "LOC_UI_CREATE_GAME_STARTING_AGE"
						}
						class={`font-title uppercase civ-select-age-text ${isMobile ? "whitespace-nowrap mb-4" : ""}`}
					/>
					<L10n.Stylize
						text={ageModel.getAgeName(selectedAge()) || ""}
						class={`font-title uppercase font-black civ-select-age-type-text ${isMobile ? "mb-4" : "font-fit-shrink mb-2"}`}
					/>
					<Popup.Trigger name="age-select">
						<AudioContextProvider segment="AgeSelectPopup">
							<Activatable
								class="civ-details-age-banner relative"
								disabled={isInGame}
								disableFocus={true}
								hotkeyAction={"shell-action-3"}
							>
								<div class="absolute inset-0 flex flex-col items-center justify-end group">
									<div class="absolute inset-0 img-unit-panelbox pointer-events-none" />
									<div
										class="absolute inset-0"
										style={{
											"background-image": `url(${UI.getIconBLP(selectedAge(), "BACKGROUND_VERT")})`,
											"background-position": "center center",
											"background-size": "cover",
										}}
									/>
									<div class="create-game-hub-bottom-gradient absolute left-0 bottom-0" />
									<div class="absolute inset-0 w-full h-full border-2 border-secondary-3" />
									<div class="img-rollover-highlight absolute inset-0 opacity-0 group-focus\:opacity-100 group-hover\:opacity-100 group-pressed\:opacity-100 pointer-events-none" />
									<div
										class="flex items-center justify-center size-36 relative mb-4"
										style={{
											width: Layout.pixels(132),
											height: Layout.pixels(132),
											"background-image": "url(blp:hud_sub_circle_dis_128x128)",
											"background-repeat": "no-repeat",
											"background-size": "cover",
										}}
									>
										<Icon
											name={ageModel.selectedAge.icon}
											class="size-24 -bottom-px relative"
										/>
									</div>
									<NavHelp class="absolute bottom-2 right-2" />
								</div>
							</Activatable>
						</AudioContextProvider>
					</Popup.Trigger>
				</div>
				<div
					class={`flex flex-col ${isMobile && isUnlocks ? "w-3\\/4 ml-4" : "w-187"} h-full relative`}
					style={{ color: "#1B1B1B" }}
				>
					<Tab class={`flex flex-col flex-auto ${isMobile && isUnlocks ? "mt-6" : "mt-8"}`}>
						<VSlot
							disableFocus={true}
							class="flex-auto"
						>
							<Tab.Output />
						</VSlot>

						<CreateGameTabPips />
						<Tab.Item
							name="civ-general"
							title={() => "General"}
							body={() => <CivGeneralInfo />}
						/>
						<Tab.Item
							name="civ-buildings"
							title={() => "Buildings"}
							body={() => <CivBuildingsInfo />}
						/>
						<Tab.Item
							name="civ-units"
							title={() => "Units"}
							body={() => <CivUnitsInfo />}
						/>
						<Tab.Item
							name="civ-traditiions"
							title={() => "Traditions"}
							body={() => <CivTraditionsInfo />}
						/>
						<Show when={civ().unlocks.length > 0 || civ().unlockedBy.length > 0}>
							<Tab.Item
								name="civ-age-unlocks"
								title={() => "Age Unlocks"}
								body={() => <CivUnlocksInfo isUnlocks={isUnlocks} />}
							/>
						</Show>
					</Tab>
					<div
						class={`flex flex-row ${isMobile && isUnlocks ? "my-3" : "mb-8 mt-4"} items-center justify-center`}
					>
						<Show when={!isUnlocks}>
							<div class="filigree-h4-left mt-3" />
							<HeroButton2
								class="civ-details-continue-button"
								disabled={civ().isLocked}
								onActivate={() => {
									flowContext!.activateNext();
									//reset filters
									const ageFilter = createAgeFilterModel();
									ageFilter.reset();
									attrFilter.reset();
								}}
								autoFocus={!civ().isLocked}
							>
								<L10n.Stylize text="LOC_GENERIC_SELECT" />
							</HeroButton2>
							{/* Create a place to park the cursor so this view can get focus correctly on controller when everything is disabled */}
							<AudioContextProvider segment="CivilizationDetails/ControllerHack">
								<Activatable
									data-name="focus-parking"
									disabled={!civ().isLocked}
									autoFocus={civ().isLocked}
								/>
							</AudioContextProvider>
							<div class="filigree-h4-right mt-3" />
						</Show>
					</div>
				</div>
			</div>
		</div>
	);
};

export const CivDetails = ComponentRegistry.register({
	name: "CivDetails",
	createInstance: CivDetailsComponent,
	styles: [style],
});
